import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro: the shippable audit — 11 rules, both bars, no disagreement","description":"","frontmatter":{"title":"Retro: the shippable audit — 11 rules, both bars, no disagreement","type":"retro","date":"2026-10"},"headers":[],"relativePath":"graphopt/project/retros/shippable-audit.md","filePath":"vendored/graphopt/project/retros/shippable-audit.md"}`),a={name:`graphopt/project/retros/shippable-audit.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-the-shippable-audit-—-11-rules-both-bars-no-disagreement" tabindex="-1">Retro: the shippable audit — 11 rules, both bars, no disagreement <a class="header-anchor" href="#retro-the-shippable-audit-—-11-rules-both-bars-no-disagreement" aria-label="Permalink to “Retro: the shippable audit — 11 rules, both bars, no disagreement”">​</a></h1><p>Context: <code>project/retros/corpus-round-4.md</code> (the <code>shippable: 0 -&gt; 11</code> claim), <code>project/retros/derivable-gate.md</code> (the truth-gate tightening) and <code>project/retros/admission-gauntlet.md</code> (the gauntlet itself).</p><p>Corpus round 4 reported <strong><code>shippable: 0 -&gt; 11</code></strong> from the pipeline&#39;s own <code>measure</code>. That is the <em>pipeline&#39;s</em> verdict — the candidate ship bar — not the gauntlet&#39;s admission bar. This audit runs each of the 11 through the full gauntlet (<code>evidence.run_gauntlet</code>) and reports the result honestly.</p><p><strong>Headline: all 11 are <code>usable: yes</code>.</strong> The two bars do not disagree anywhere on this set. The interesting finding is <em>why</em>, and the two places where they would disagree on other inputs.</p><h2 id="the-per-rule-verdict" tabindex="-1">The per-rule verdict <a class="header-anchor" href="#the-per-rule-verdict" aria-label="Permalink to “The per-rule verdict”">​</a></h2><p>Each of the 11 was stored as a <code>kind=&quot;law&quot;</code> object and run through <code>run_gauntlet</code> on the real corpus (<code>default_gauntlet_corpus</code>: bench + models + intake, <code>ALL_RULES</code>, <code>TermCaseSink</code>):</p><table tabindex="0"><thead><tr><th>rule</th><th>pipeline <code>shippable</code></th><th>gauntlet <code>usable</code></th><th>first refusal</th></tr></thead><tbody><tr><td><code>sub_self</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>grammar:pow_one</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>reshape_reshape</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>square_neg</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>factor_left</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>factor_right</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>factor_sub_left</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>factor_sub_right</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>neg_add</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>exp_add</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr><tr><td><code>sub_neg</code></td><td>yes</td><td><strong>yes</strong></td><td>— cleared</td></tr></tbody></table><p><strong>Zero refusals</strong> — no rule stops at truth, novelty, typed-pay, closure or cert. Every one fires exactly once on its site (<code>fires == fires_typed == paid</code>, <code>fires_ill_typed == 0</code>, <code>verify_fail == 0</code>, <code>cert_fail == 0</code>, <code>closure_ratio &lt;= 1.67x</code>).</p><p>The stage-4 truth detail for every rule is the <em>unguarded</em> form — <code>numeric=True derivable=False</code> (or <code>derivable=True</code> for <code>sub_neg</code>) — with <strong>no <code>guarded:</code> sweep</strong>. That is the whole story.</p><h2 id="why-they-agree-—-the-gauntlet-s-teeth-are-dormant-here" tabindex="-1">Why they agree — the gauntlet&#39;s teeth are dormant here <a class="header-anchor" href="#why-they-agree-—-the-gauntlet-s-teeth-are-dormant-here" aria-label="Permalink to “Why they agree — the gauntlet&#39;s teeth are dormant here”">​</a></h2><p>The gauntlet&#39;s one genuinely stricter stage is the <strong>guarded-region sweep</strong> (<code>_guarded_truth</code>, stage 4 for a <code>cond</code>-carrying object). All 11 rules are <strong>unguarded</strong> — <code>rule.cond is None and rule.check is None</code> — so <code>_truth_gate</code> takes its unguarded branch:</p><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">ok </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> evd</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">num_true </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">is</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> not</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> False</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;"> and</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> (</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">    evd</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">derivable </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">or</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> evd</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">.</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">num_true </span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">is</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> True</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span></span></code></pre></div><p>which is the pipeline&#39;s own <code>Evidence.truth</code> (<code>derivable or num_true is True</code>) plus the derivable-gate tightening (<code>num_true is not False</code>). Every one of the 11 measures <code>num_true is True</code>, so the tightening&#39;s extra clause never fires and the two bars coincide <em>by construction</em>. The gauntlet does not independently re-verify these — it inherits the pipeline&#39;s single-instance numeric oracle, exactly as an unguarded law always has.</p><h2 id="the-two-systematic-differences-real-but-dormant" tabindex="-1">The two systematic differences (real, but dormant) <a class="header-anchor" href="#the-two-systematic-differences-real-but-dormant" aria-label="Permalink to “The two systematic differences (real, but dormant)”">​</a></h2><p>The bars are not the same predicate; they diverge on inputs the 11 do not present. Both divergences are pinned as unit facts in the new test file.</p><table tabindex="0"><thead><tr><th>dimension</th><th>pipeline <code>shippable</code></th><th>gauntlet <code>usable</code></th><th>who is stricter</th></tr></thead><tbody><tr><td>truth, unguarded</td><td><code>derivable or num_true is True</code></td><td><code>num_true is not False and (…)</code></td><td><strong>gauntlet</strong> — a measured counterexample outranks a derivation</td></tr><tr><td>truth, guarded</td><td>the same <code>truth</code> (no sweep)</td><td>full guarded-region sweep</td><td><strong>gauntlet</strong> — by far</td></tr><tr><td>closure</td><td><code>cert_fail == 0</code> (every <code>add_cert</code>)</td><td><em>attributable</em> cert failures only</td><td><strong>pipeline</strong> — the gauntlet excuses ambient failures</td></tr><tr><td>instance</td><td><code>proposal.instance</code> (hand-written)</td><td>rebuilt proposal carries none → <code>_instance_from_match</code></td><td>latent (grammar rules)</td></tr></tbody></table><ul><li><strong>Truth (derivable vs counterexample).</strong> The derivable-gate retro explicitly flagged <code>pipeline.Evidence.truth</code> as &quot;the sibling instance … out of this change&#39;s scope&quot;. This audit confirms it is a real divergence: <code>Evidence(num_true=False, derivable=True).truth</code> is <code>True</code> (pipeline), while the gauntlet&#39;s unguarded gate returns <code>False</code>. None of the 11 is in that state.</li><li><strong>Closure (ambient cert).</strong> The admission-gauntlet retro decided the gauntlet charges only failures <em>attributable</em> to the object, because the pipeline&#39;s aggregate <code>cert_fail</code> counts a pre-existing baseline break (<code>intake:SincKernel</code>). So a rule with an ambient failure is pipeline-<code>shippable=False</code> but gauntlet-<code>usable=True</code> — the gauntlet is deliberately the <em>looser</em> one here. All 11 have <code>cert_fail == 0</code>, so it does not bite.</li><li><strong>Instance loss.</strong> <code>_measure_gate</code> rebuilds the proposal from the stored record, which carries no <code>instance</code>; the grammar proposals&#39; hand-written instance is dropped and <code>_instance_from_match</code> is used instead. For <code>grammar:pow_one</code> a real match exists, so the verdict is unchanged — but a grammar rule with a concrete instance and no real match would measure differently under the two bars (it cannot ship anyway, since <code>fires &gt; 0</code> needs a site).</li></ul><h2 id="the-design-question-—-align-or-document" tabindex="-1">The design question — align or document? <a class="header-anchor" href="#the-design-question-—-align-or-document" aria-label="Permalink to “The design question — align or document?”">​</a></h2><p><strong>Recommendation: document, do not change pipeline semantics.</strong> The two properties answer different questions and their divergences are each independently justified:</p><ul><li><code>pipeline.Evidence.shippable</code> is the <strong>candidate</strong> bar — a proposal measured over the corpus, ranked, reported. It has no object, no <code>cond</code>, no stored record.</li><li><code>evidence.run_gauntlet(...).usable</code> is the <strong>stored-object</strong> bar — a declared record admitted through the same ladder a shipped law faced, with a guarded sweep and a cert replay the pipeline does not run.</li></ul><p>They are aligned in <em>intent</em> (truth ∧ new ∧ typed ∧ pays ∧ bounded-closure ∧ cert-clean) and identical for the unconditional, hook-free laws — which is the whole of round 4&#39;s yield. The two genuine asymmetries are deliberate:</p><ul><li>the gauntlet&#39;s truth tightening is the <em>point</em> of the derivable-gate change (a proof must yield to a measured site);</li><li>the gauntlet&#39;s closure leniency is the <em>point</em> of the ambient-cert decision (do not condemn an object for a corpus instability).</li></ul><p>The one item worth a follow-up is the <strong>pipeline&#39;s <code>cert_fail == 0</code></strong>: it is over-strict relative to the gauntlet, because it charges ambient failures the gauntlet deliberately excuses. Aligning it would be a pipeline-semantics change and is <strong>out of this audit&#39;s scope</strong> — reported here, not made. (The derivable-gate retro&#39;s flagged <code>pipeline.Evidence.truth</code> follow-up is the same class: a real latent divergence, dormant on the 11.)</p><h2 id="are-the-11-useful-—-honest-assessment" tabindex="-1">Are the 11 <em>useful</em>? — honest assessment <a class="header-anchor" href="#are-the-11-useful-—-honest-assessment" aria-label="Permalink to “Are the 11 useful? — honest assessment”">​</a></h2><p><strong>They are true, well-typed, and they pay — but only on the corpus grown to spell them.</strong> Measured against the <em>baseline</em> corpus (bench + models, no intake) all 11 are <code>match=0 fires=0 paid=0 shippable=False</code>. Every firing site is a round-4 intake workload:</p><table tabindex="0"><thead><tr><th>rule</th><th>site(s)</th><th>drop</th><th>derivable</th></tr></thead><tbody><tr><td><code>factor_left</code></td><td><code>intake:SharedFactorMixture</code>, <code>intake:QuadraticFeature</code></td><td>33%</td><td>no</td></tr><tr><td><code>factor_right</code></td><td><code>intake:SharedFactorMixtureRight</code></td><td>33%</td><td>no</td></tr><tr><td><code>factor_sub_left</code></td><td><code>intake:SharedFactorContrast</code></td><td>33%</td><td>no</td></tr><tr><td><code>factor_sub_right</code></td><td><code>intake:SharedFactorContrastRight</code></td><td>33%</td><td>no</td></tr><tr><td><code>exp_add</code></td><td><code>intake:ExpProductHead</code></td><td>33%</td><td>no</td></tr><tr><td><code>neg_add</code></td><td><code>intake:NegatedSum</code></td><td>33%</td><td>no</td></tr><tr><td><code>reshape_reshape</code></td><td><code>intake:DoubleReshapeHead</code></td><td>50%</td><td>no</td></tr><tr><td><code>square_neg</code></td><td><code>intake:SquareNegHead</code></td><td>50%</td><td>no</td></tr><tr><td><code>grammar:pow_one</code></td><td><code>intake:PowOneHead</code></td><td>100%</td><td>no</td></tr><tr><td><code>sub_self</code></td><td><code>intake:ScalarSelfCancel</code></td><td>100%</td><td>no</td></tr><tr><td><code>sub_neg</code></td><td><code>intake:SubNegBias</code></td><td>0% (pays)</td><td><strong>yes</strong></td></tr></tbody></table><p>So &quot;<code>shippable: 0 -&gt; 11</code>&quot; is a statement about the <em>corpus&#39;s</em> new spellings, not about real networks: none of the 11 is reached by a pre-existing bench or model. The 11 are, honestly:</p><ul><li><strong>real laws</strong> (numerically true within the oracle&#39;s fp64 tolerance, not library duplicates — <code>relation=new</code>), and they pay;</li><li><strong>elementary algebra</strong> — <code>x-x=0</code>, <code>x**1=x</code>, <code>(-x)^2=x^2</code>, <code>x-(-y)=x+y</code>, <code>(-x)+(-y)=-(x+y)</code>, <code>e^x e^y=e^{x+y}</code>, <code>x*y ± x*z=x*(y±z)</code> — the textbook identities the library lacked (it already had the <em>matmul/linear</em> factoring controls, but not the elementwise ones);</li><li><strong>spelled by contrived micro-modules</strong> — several round-4 workloads are two-line <code>nn.Module</code>s written to produce the exact pattern (<code>(-x)+(-y)</code>, <code>x**1</code>, <code>s-s</code>), not natural model code. The shared-factor and double-reshape sites are the most plausible; the scalar-corner and pure-grammar ones are spellings.</li></ul><p>Verdict: the 11 are <em>usable</em> in the gauntlet&#39;s sense and <em>correct</em>, but their demonstrated usefulness is <strong>corpus-circular</strong> — they are recognized where round 4 deliberately taught the corpus to spell them. That is not a defect in the rules or the gates; it is the honest reading of what &quot;shipped&quot; measures here.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to “Tests”">​</a></h2><p><code>tests/test_discovery_shippable_audit.py</code> (new) pins the audit&#39;s verdict per rule on a small synthetic corpus carrying one concrete spelling site each (fast — the whole file runs in ~4 s, no heavy intake corpus):</p><ul><li><code>test_shippable_rule_clears_the_gauntlet</code> (parametrized over all 11) — <code>usable</code>, every stage passed, <code>fires == 1</code>, <code>paid == 1</code>, <code>cert_fail == 0</code>.</li><li><code>test_pipeline_shippable_and_gauntlet_usable_agree</code> (parametrized) — <code>measure().shippable is True</code>, <code>run_gauntlet().usable is True</code>, and the two are equal.</li><li><code>test_shippable_rules_are_unguarded</code> (parametrized) — the structural reason: <code>cond is None and check is None</code>.</li><li><code>test_gauntlet_truth_takes_the_unguarded_branch</code> — the truth gate leaves <code>synth_region is None</code> and the detail has no <code>guarded:</code>.</li><li><code>test_gauntlet_truth_is_stricter_on_a_derivable_counterexample</code> — the pipeline/gauntlet truth divergence (unit).</li><li><code>test_gauntlet_closure_is_looser_on_an_ambient_cert_failure</code> — the closure divergence (unit).</li></ul><h2 id="gates" tabindex="-1">Gates <a class="header-anchor" href="#gates" aria-label="Permalink to “Gates”">​</a></h2><p><code>pytest tests/test_discovery_gauntlet.py tests/test_discovery_evidence.py tests/test_discovery_intake.py -q</code> and <code>ruff check</code> / <code>ruff format --check</code> / <code>ty check</code> / <code>radon_ratchet</code> / <code>vulture</code> are clean <strong>against the committed tree</strong>.</p><blockquote><p><em>Concurrent working-tree state.</em> The audit was run while the tree carried an in-flight, uncommitted sibling edit (<code>oracle.py</code>, <code>laws/tensor.py</code>, <code>tests/test_cond_laws.py</code> — the value-bank widening). That edit moves the enumeration, and three <code>test_discovery_gauntlet.py</code> tests that read region counts directly (<code>test_sdpa_fold_addmul_starved_at_the_default_cap</code>, <code>test_guarded_truth_escalates_a_starved_region</code>, <code>test_truth_gate_uses_the_selective_cap</code>) fail against it — the starved <code>sdpa_fold_addmul</code> window now accepts 6 sites instead of 0. Verified by re-running the gate in a <code>git worktree</code> at HEAD with the committed <code>oracle.py</code>: <strong>115 passed</strong>. None of those tests touch this audit; all six new tests here pass in both trees.</p></blockquote><p>No new suppressions. <code>pipeline.py</code>, <code>evidence.py</code>, <code>oracle.py</code>, <code>intake.py</code> untouched — the audit is read-only outside its own test file and this retro.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><ul><li><strong>Measured, not proven.</strong> The gauntlet&#39;s truth for an unguarded law is the <em>single-instance</em> numeric oracle; a counterexample outside the sampled instance is not caught. This is the same epistemic bound the shipped laws were admitted under.</li><li><strong>Corpus-relative yield.</strong> &quot;Pays&quot; means pays on the corpus the pipeline measures; the 11 pay only on round-4 intake sites.</li><li><strong>The two asymmetries are dormant, not absent.</strong> A future rule in a <code>derivable ∧ num_true=False</code> state, or one with an ambient cert failure, will make the pipeline and the gauntlet disagree — by design. That is the case to watch, not this set.</li></ul>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};